use thiserror::Error;

#[derive(Debug, Error)]
pub enum FrictionError {
    #[error("I/O error: {0}")]
    Io(#[from] std::io::Error),
    #[error("JSON parse error: {0}")]
    Json(#[from] serde_json::Error),
}

use crate::errors::FrictionError;
use chrono::{DateTime, Utc};
use serde::Deserialize;
use serde_json::{Map, Value};
use std::io::{self, BufRead};

#[derive(Debug, Deserialize)]
pub struct Entry {
    #[serde(default)]
    pub line: usize,
    #[serde(default)]
    pub timestamp: Option<String>,
    #[serde(default)]
    pub level: Option<String>,
    #[serde(default)]
    pub message: Option<String>,
    #[serde(default)]
    pub fields: Option<Map<String, Value>>,
}

impl Entry {
    pub fn parsed_timestamp(&self) -> Option<DateTime<Utc>> {
        self.timestamp
            .as_ref()
            .and_then(|s| s.parse::<DateTime<Utc>>().ok())
    }

    pub fn duration_ms(&self) -> Option<i64> {
        self.fields
            .as_ref()
            .and_then(|m| m.get("duration_ms"))
            .and_then(|v| v.as_i64())
    }
}

pub fn read_stdin() -> Result<Vec<Entry>, FrictionError> {
    let stdin = io::stdin();
    let mut entries = Vec::new();

    for (idx, line) in stdin.lock().lines().enumerate() {
        let line = line?;
        if line.trim().is_empty() {
            continue;
        }
        let mut entry: Entry = serde_json::from_str(&line)?;
        if entry.line == 0 {
            entry.line = idx + 1;
        }
        entries.push(entry);
    }

    Ok(entries)
}

use crate::reader::Entry;
use std::collections::HashMap;

#[derive(Debug, Default)]
pub struct MessageCounts {
    counts: HashMap<String, Vec<usize>>,
}

impl MessageCounts {
    pub fn add(&mut self, entry: &Entry) {
        if let Some(msg) = &entry.message {
            self.counts
                .entry(msg.to_string())
                .or_default()
                .push(entry.line);
        }
    }

    pub fn repeated(&self, min_occurrences: usize) -> Vec<(String, Vec<usize>)> {
        self.counts
            .iter()
            .filter_map(|(msg, lines)| {
                if lines.len() >= min_occurrences {
                    Some((msg.clone(), lines.clone()))
                } else {
                    None
                }
            })
            .collect()
    }
}

use crate::counters::MessageCounts;
use crate::reader::Entry;
use chrono::{DateTime, Utc};

const SLOW_THRESHOLD_MS: i64 = 500;
const GAP_THRESHOLD_SECONDS: i64 = 60;
const REPEATED_MIN_OCCURRENCES: usize = 2;

#[derive(Debug)]
pub struct FrictionPoint {
    pub line: usize,
    pub timestamp: Option<String>,
    pub detail: String,
}

#[derive(Debug)]
pub struct SlowOp {
    pub line: usize,
    pub timestamp: Option<String>,
    pub duration_ms: i64,
    pub message: String,
}

#[derive(Debug)]
pub struct LongGap {
    pub from_line: usize,
    pub to_line: usize,
    pub from_ts: String,
    pub to_ts: String,
    pub gap_seconds: i64,
}

#[derive(Debug)]
pub struct RepeatedFailureGroup {
    pub message: String,
    pub occurrences: Vec<FrictionPoint>,
}

#[derive(Debug, Default)]
pub struct FrictionSummary {
    pub total_lines: usize,

    pub errors: Vec<FrictionPoint>,
    pub warnings: Vec<FrictionPoint>,
    pub slow_ops: Vec<SlowOp>,
    pub long_gaps: Vec<LongGap>,
    pub repeated_failures: Vec<RepeatedFailureGroup>,
}

pub fn analyse(entries: &[Entry]) -> FrictionSummary {
    let mut summary = FrictionSummary {
        total_lines: entries.len(),
        ..Default::default()
    };

    let mut prev_ts: Option<(DateTime<Utc>, usize)> = None;
    let mut msg_counts = MessageCounts::default();

    for e in entries {
        // Levels
        if let Some(level) = &e.level {
            let point = FrictionPoint {
                line: e.line,
                timestamp: e.timestamp.clone(),
                detail: e.message.clone().unwrap_or_default(),
            };

            match level.as_str() {
                "ERROR" => summary.errors.push(point),
                "WARN" => summary.warnings.push(point),
                _ => {}
            }
        }

        // Slow operations
        if let Some(ms) = e.duration_ms() {
            if ms > SLOW_THRESHOLD_MS {
                summary.slow_ops.push(SlowOp {
                    line: e.line,
                    timestamp: e.timestamp.clone(),
                    duration_ms: ms,
                    message: e.message.clone().unwrap_or_default(),
                });
            }
        }

        // Long gaps
        if let Some(ts) = e.parsed_timestamp() {
            if let Some((prev, prev_line)) = prev_ts {
                let gap = (ts - prev).num_seconds();
                if gap > GAP_THRESHOLD_SECONDS {
                    let from_ts = entries
                        .iter()
                        .find(|x| x.line == prev_line)
                        .and_then(|x| x.timestamp.clone())
                        .unwrap_or_else(|| prev.to_rfc3339());
                    let to_ts = e.timestamp.clone().unwrap_or_else(|| ts.to_rfc3339());

                    summary.long_gaps.push(LongGap {
                        from_line: prev_line,
                        to_line: e.line,
                        from_ts,
                        to_ts,
                        gap_seconds: gap,
                    });
                }
            }
            prev_ts = Some((ts, e.line));
        }

        // Repeated messages
        msg_counts.add(e);
    }

    // Build repeated failure groups
    for (msg, lines) in msg_counts.repeated(REPEATED_MIN_OCCURRENCES) {
        let mut occurrences = Vec::new();
        for line in lines {
            if let Some(entry) = entries.iter().find(|e| e.line == line) {
                occurrences.push(FrictionPoint {
                    line,
                    timestamp: entry.timestamp.clone(),
                    detail: String::new(),
                });
            }
        }
        summary.repeated_failures.push(RepeatedFailureGroup {
            message: msg,
            occurrences,
        });
    }

    summary
}

use crate::patterns::{FrictionSummary, LongGap, RepeatedFailureGroup};

pub fn print(summary: &FrictionSummary) {
    println!("FrictionDetect Report");
    println!("=====================\n");

    println!("Total:");
    println!("  Lines analysed: {}", summary.total_lines);
    println!("  Errors: {}", summary.errors.len());
    println!("  Warnings: {}", summary.warnings.len());
    println!("  Slow operations: {}", summary.slow_ops.len());
    println!("  Long gaps: {}", summary.long_gaps.len());
    println!("  Repeated failures: {}", summary.repeated_failures.len());
    println!();

    println!("Further Details:");
    println!("---------------\n");

    print_errors(summary);
    print_warnings(summary);
    print_slow_ops(summary);
    print_long_gaps(summary);
    print_repeated_failures(summary);
}

fn print_errors(summary: &FrictionSummary) {
    println!("Errors:");
    if summary.errors.is_empty() {
        println!("  (none)\n");
        return;
    }
    for e in &summary.errors {
        let ts = e.timestamp.as_deref().unwrap_or("-");
        println!("  [line {}]  {}  {}", e.line, ts, e.detail);
    }
    println!();
}

fn print_warnings(summary: &FrictionSummary) {
    println!("Warnings:");
    if summary.warnings.is_empty() {
        println!("  (none)\n");
        return;
    }
    for w in &summary.warnings {
        let ts = w.timestamp.as_deref().unwrap_or("-");
        println!("  [line {}]  {}  {}", w.line, ts, w.detail);
    }
    println!();
}

fn print_slow_ops(summary: &FrictionSummary) {
    println!("Slow Operations:");
    if summary.slow_ops.is_empty() {
        println!("  (none)\n");
        return;
    }
    for s in &summary.slow_ops {
        let ts = s.timestamp.as_deref().unwrap_or("-");
        println!("  [line {}]   [{} ms]   {}   {}", s.line, s.duration_ms, ts, s.message);
    }
    println!();
}

fn print_long_gaps(summary: &FrictionSummary) {
    println!("Long Gaps:");
    if summary.long_gaps.is_empty() {
        println!("  (none)\n");
        return;
    }
    for LongGap {
        from_line,
        to_line,
        from_ts,
        to_ts,
        gap_seconds,
    } in &summary.long_gaps
    {
        println!(
            "  [line {} → line {}]  {} → {} ({} seconds)",
            from_line, to_line, from_ts, to_ts, gap_seconds
        );
    }
    println!();
}

fn print_repeated_failures(summary: &FrictionSummary) {
    println!("Repeated Failures:");
    if summary.repeated_failures.is_empty() {
        println!("  (none)\n");
        return;
    }
    for RepeatedFailureGroup { message, occurrences } in &summary.repeated_failures {
        println!("  {} ({} occurrences)", message, occurrences.len());
        for o in occurrences {
            let ts = o.timestamp.as_deref().unwrap_or("-");
            println!("    - [line {}]  {}", o.line, ts);
        }
        println!();
    }
}

mod counters;
mod errors;
mod patterns;
mod reader;
mod report;

use crate::errors::FrictionError;
use clap::{Parser, Subcommand};
use std::fs::File;
use std::io::{self, BufRead, BufReader, IsTerminal};
use std::path::PathBuf;

/// FrictionDetect — analyse structured JSONL logs for friction patterns.
///
/// This tool consumes JSON Lines (JSONL) logs produced by tools like LogTidy
/// and identifies friction indicators such as:
///   • errors and warnings
///   • slow operations
///   • long gaps between events
///   • repeated failures
#[derive(Parser)]
#[command(
    name = "frictiondetect",
    version,
    about = "Analyse structured logs for friction patterns",
    long_about = None
)]
struct Cli {
    #[command(subcommand)]
    command: Option<Commands>,
}

/// Subcommands
#[derive(Subcommand)]
enum Commands {
    /// Analyse structured JSONL logs (from file or stdin)
    Analyse {
        /// Optional input file (JSONL). If omitted, stdin is used.
        #[arg(short, long)]
        file: Option<PathBuf>,
    },

    /// Show example input/output
    Sample,

    /// Show condensed documentation
    Docs,

    /// Show tool information
    About,
}

fn main() -> Result<(), FrictionError> {
    let cli = Cli::parse();

    match cli.command {
        Some(Commands::Analyse { file }) => {
            let entries = match file {
                Some(path) => read_file(&path)?,
                None => reader::read_stdin()?,
            };

            let summary = patterns::analyse(&entries);
            report::print(&summary);
        }

        Some(Commands::Sample) => {
            print_sample();
        }

        Some(Commands::Docs) => {
            print_docs();
        }

        Some(Commands::About) => {
            print_about();
        }

        None => {
            print_main_menu();
        }
    }

    Ok(())
}

/// Read JSONL entries from a file
fn read_file(path: &PathBuf) -> Result<Vec<reader::Entry>, FrictionError> {
    let file = File::open(path)?;
    let reader = BufReader::new(file);

    let mut entries = Vec::new();
    for (idx, line) in reader.lines().enumerate() {
        let line = line?;
        if line.trim().is_empty() {
            continue;
        }
        let mut entry: reader::Entry = serde_json::from_str(&line)?;
        if entry.line == 0 {
            entry.line = idx + 1;
        }
        entries.push(entry);
    }

    Ok(entries)
}

/// Main menu (shown when no subcommand is provided)
fn print_main_menu() {
    println!("FrictionDetect — Analyse structured logs for friction patterns");
    println!();
    println!("Commands:");
    println!("  analyse    Analyse structured JSONL logs");
    println!("  sample     Show example input/output");
    println!("  docs       Show condensed documentation");
    println!("  about      Show tool information");
    println!("  help       Show help");
}

/// Example usage and sample JSONL
fn print_sample() {
    println!("Example input (JSONL):");
    println!(r#"  {{"line":1,"timestamp":"2024-01-01T12:00:00Z","level":"INFO","message":"Start","fields":{{}}}}"#);
    println!(r#"  {{"line":2,"timestamp":"2024-01-01T12:00:01Z","level":"ERROR","message":"Failed","fields":{{"duration_ms":800}}}}"#);
    println!(r#"  {{"line":3,"timestamp":"2024-01-01T12:00:02Z","level":"INFO","message":"Retry","fields":{{}}}}"#);
    println!();
    println!("Run:");
    println!("  frictiondetect analyse --file sample.jsonl");
}

/// Condensed documentation
fn print_docs() {
    println!("Purpose:");
    println!("  Analyse structured JSONL logs and identify friction patterns.");
    println!();
    println!("Usage:");
    println!("  frictiondetect analyse --file <path>");
    println!("  cat logs.jsonl | frictiondetect analyse");
    println!();
    println!("Input:");
    println!("  - JSON Lines (JSONL), one JSON object per line");
    println!("  - Typically produced by LogTidy");
    println!();
    println!("Output:");
    println!("  - Errors and warnings");
    println!("  - Slow operations");
    println!("  - Long gaps between events");
    println!("  - Repeated failures");
    println!();
    println!("Examples:");
    println!("  For example input/output, run:");
    println!("    frictiondetect sample");
    println!();
    println!("Full Documentation:");
    println!("  https://github.com/musman-uk/frictiondetect/blob/main/Documentation.md");
}

/// About information
fn print_about() {
    println!(
        "FrictionDetect v{} · {}",
        env!("CARGO_PKG_VERSION"),
        env!("CARGO_PKG_LICENSE")
    );
    println!("https://github.com/musman-uk/frictiondetect");
    println!();

    if io::stdout().is_terminal() {
        println!(
            "\x1b]8;;https://github.com/musman-uk\x1b\\\x1b[3mMohammed Usman\x1b[0m\x1b]8;;\x1b\\"
        );
        println!();
        println!("\x1b[2m© Mohammed Usman\x1b[0m");
    } else {
        println!("Mohammed Usman");
        println!();
        println!("© Mohammed Usman");
    }
}

use assert_cmd::Command;

#[test]
fn report_contains_totals_and_details() {
    let input = r#"
{"line":1,"timestamp":"2024-03-10T12:00:01Z","level":"INFO","message":"Starting service"}
{"line":2,"timestamp":"2024-03-10T12:00:03Z","level":"WARN","message":"Slow response from /api/orders","fields":{"duration_ms":650}}
{"line":3,"timestamp":"2024-03-10T12:00:10Z","level":"ERROR","message":"Timeout while calling payment gateway","fields":{"duration_ms":1200}}
{"line":4,"timestamp":"2024-03-10T12:00:30Z","level":"ERROR","message":"Payment failed"}
{"line":5,"timestamp":"2024-03-10T12:00:32Z","level":"ERROR","message":"Timeout while calling payment gateway"}
{"line":6,"timestamp":"2024-03-10T12:00:33Z","level":"ERROR","message":"Timeout while calling payment gateway"}
{"line":7,"timestamp":"2024-03-10T12:05:33Z","level":"INFO","message":"Background job started"}
{"line":8,"timestamp":"2024-03-10T12:05:34Z","level":"INFO","message":"Completed request","fields":{"duration_ms":1200}}
{"line":9,"timestamp":"2024-03-10T12:05:35Z","level":"INFO","message":"/api/slow","fields":{"duration_ms":2000}}
{"line":10,"timestamp":"2024-03-10T12:05:37Z","level":"ERROR","message":"Timeout while calling payment gateway"}
"#;

    let assert = Command::cargo_bin("frictiondetect")
        .unwrap()
        .arg("analyse")
        .write_stdin(input)
        .assert()
        .success();

    let stdout = String::from_utf8_lossy(&assert.get_output().stdout);

    assert!(stdout.contains("FrictionDetect Report"));
    assert!(stdout.contains("Lines analysed: 10"));
    assert!(stdout.contains("Errors: 5"));
    assert!(stdout.contains("Warnings: 1"));
    assert!(stdout.contains("Slow operations: 4"));
    assert!(stdout.contains("Long gaps: 1"));
    assert!(stdout.contains("Repeated failures: 1"));
    assert!(stdout.contains("[1200 ms]   2024-03-10T12:05:34Z   Completed request"));
}

#[test]
fn standalone_jsonl_without_line_numbers_defaults_to_one_based_index() {
    let input = concat!(
        r#"{"timestamp":"2024-03-10T12:00:01Z","level":"INFO","message":"Boot","fields":null}"#,
        "\n",
        r#"{"timestamp":"2024-03-10T12:00:02Z","level":"ERROR","message":"DB failure","fields":{"duration_ms":900}}"#,
        "\n",
    );

    let assert = Command::cargo_bin("frictiondetect")
        .unwrap()
        .arg("analyse")
        .write_stdin(input)
        .assert()
        .success();

    let stdout = String::from_utf8_lossy(&assert.get_output().stdout);

    assert!(stdout.contains("Lines analysed: 2"));
    assert!(stdout.contains("Errors: 1"));
    assert!(stdout.contains("Slow operations: 1"));
    assert!(stdout.contains("[line 2]  2024-03-10T12:00:02Z  DB failure"));
}

#[test]
fn analyse_file_fixture_and_missing_file_error() {
    let assert = Command::cargo_bin("frictiondetect")
        .unwrap()
        .args(["analyse", "--file", "tests/fixtures/sample1.jsonl"])
        .assert()
        .success();

    let stdout = String::from_utf8_lossy(&assert.get_output().stdout);
    assert!(stdout.contains("Lines analysed: 10"));
    assert!(stdout.contains("Errors: 5"));
    assert!(stdout.contains("Long gaps: 1"));

    Command::cargo_bin("frictiondetect")
        .unwrap()
        .args(["analyse", "--file", "tests/fixtures/does-not-exist.jsonl"])
        .assert()
        .failure();
}

#[test]
fn empty_stdin_produces_zero_counts() {
    let assert = Command::cargo_bin("frictiondetect")
        .unwrap()
        .arg("analyse")
        .write_stdin("\n   \n")
        .assert()
        .success();

    let stdout = String::from_utf8_lossy(&assert.get_output().stdout);
    assert!(stdout.contains("Lines analysed: 0"));
    assert!(stdout.contains("Errors: 0"));
}

#[test]
fn malformed_json_aborts_with_error() {
    let input = "{\"line\":1,\"level\":\"INFO\",\"message\":\"ok\"}\nnot valid json\n";

    Command::cargo_bin("frictiondetect")
        .unwrap()
        .arg("analyse")
        .write_stdin(input)
        .assert()
        .failure();
}

#[test]
fn about_strips_escape_codes_when_piped() {
    let assert = Command::cargo_bin("frictiondetect")
        .unwrap()
        .arg("about")
        .assert()
        .success();

    let stdout = String::from_utf8_lossy(&assert.get_output().stdout);
    assert!(stdout.contains("FrictionDetect"));
    assert!(stdout.contains("Mohammed Usman"));
    assert!(!stdout.contains("\x1b["));
    assert!(!stdout.contains("\x1b]8;;"));
}

#[test]
fn fd_alias_and_invalid_subcommand() {
    Command::cargo_bin("fd")
        .unwrap()
        .arg("--version")
        .assert()
        .success();

    let assert = Command::cargo_bin("frictiondetect")
        .unwrap()
        .arg("not-a-command")
        .assert()
        .failure();

    let stderr = String::from_utf8_lossy(&assert.get_output().stderr);
    assert!(!stderr.is_empty());
}
